    description: "The M2 chip in a portable 13\" body. Video editors, developers, and designers who need sustained performance without a heavy machine. ProMotion display, MagSafe, and all-day battery.",
    overview: "The Apple MacBook Pro 13-inch with M2 is for anyone who needs professional-grade performance in a compact, portable machine. The M2 chip delivers an 18% CPU performance gain and a 35% GPU performance gain over M1, and unlike competing laptops, it maintains that performance consistently without throttling due to heat. Whether you are compiling code, cutting 4K video, running Lightroom on a large catalogue, or running multiple virtual machines, the M2 handles it without complaint. The 13.3-inch Liquid Retina display is sharp at 2560 x 1600, covers 100% of the sRGB colour space, and reaches 500 nits of brightness. The display does not have ProMotion (120Hz) like the 14-inch Pro, but at this price point, the M2 chip more than makes up for it. Battery life is exceptional, often reaching 20 hours in mixed use, which means charging once every one to two days even with heavy use. The keyboard is Apple's Magic Keyboard with Touch ID, and the Force Touch trackpad remains the best trackpad on any laptop. The 256GB internal SSD is fast enough for most users, though if you work with large media files, consider upgrading to 512GB. This machine is ideal for Nairobi professionals who travel frequently and need a laptop that performs reliably in all conditions without needing a power socket nearby.",
